CREATE OR REPLACE FUNCTION public.project_discovery_rows() RETURNS TABLE(id uuid,slug text,teaser_title text,country_code character,technology public.technology,project_type public.project_type,lifecycle_stage public.lifecycle_stage,capacity_band text,capex_band text,instrument public.transaction_instrument,min_ticket_band text,min_ticket_sort numeric,offtake_committed_load_pct numeric,transaction_terms_published boolean,created_at timestamptz,equity_sought_band text,equity_sought_sort integer,target_close_quarter text,feasibility_complete boolean,public_funding_awarded boolean,new_load_contracted_pct numeric) LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
SELECT t.*,CASE WHEN o.equity_sought IS NULL THEN NULL WHEN o.equity_sought<1000000 THEN 'Under EUR 1M' WHEN o.equity_sought<3000000 THEN 'EUR 1-3M' WHEN o.equity_sought<5000000 THEN 'EUR 3-5M' WHEN o.equity_sought<10000000 THEN 'EUR 5-10M' ELSE 'EUR 10M and above' END,CASE WHEN o.equity_sought IS NULL THEN NULL WHEN o.equity_sought<1000000 THEN 0 WHEN o.equity_sought<3000000 THEN 1 WHEN o.equity_sought<5000000 THEN 2 WHEN o.equity_sought<10000000 THEN 3 ELSE 4 END,
CASE WHEN p.submission_published->'answers'->>'targetClose' ~ '^\d{4} Q[1-4]$' THEN p.submission_published->'answers'->>'targetClose' WHEN pr.target_close IS NOT NULL THEN to_char(pr.target_close,'YYYY')||' Q'||extract(quarter FROM pr.target_close)::text ELSE NULL END,
p.submission_published->'answers'->>'studyComplete'='yes',EXISTS(SELECT 1 FROM public.public_funding f JOIN public.financial_summary fs ON fs.id=f.financial_summary_id WHERE fs.project_id=p.id AND f.funding_status='awarded'),l.contracted_load_pct
FROM public.project_teaser_rows() t JOIN public.project p ON p.id=t.id LEFT JOIN public.project_transaction o ON o.project_id=p.id LEFT JOIN public.project_process pr ON pr.project_id=p.id LEFT JOIN public.offtake_ladder l ON l.project_id=p.id;
$$;
REVOKE ALL ON FUNCTION public.project_discovery_rows() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.project_discovery_rows() TO anon,authenticated,service_role;
CREATE VIEW public.project_discovery WITH(security_invoker=true) AS SELECT * FROM public.project_discovery_rows();
GRANT SELECT ON public.project_discovery TO anon,authenticated,service_role;